<body>
<div class="layout">
<main>
<header class="paper-head">
{{HEADER}}
</header>
<noscript><p class="note">JavaScript is off. You can read and print the questions, but answer status and export will not work. Write your answers in a separate document and share it with your tutor.</p></noscript>
<form id="exam" autocomplete="off">
{{QUESTIONS}}
</form>
<section class="submission" id="submission" aria-labelledby="submission-title">
<h2 id="submission-title">Finished? Export your attempt.</h2>
<p>Export before closing or reloading: unexported answers live only in this open page. Attach the exported JSON file in chat and ask your tutor to review your answers and reasoning. The tutor can then update your learning record.</p>
<div class="actions"><button type="button" id="export">Export my attempt</button><button type="button" class="secondary" id="retry">Start another attempt</button></div>
<p id="feedback" role="status" aria-live="polite"></p>
<details id="export-panel"><summary>Copy the attempt JSON if the download did not start</summary><label class="field-label" for="export-output">Attempt JSON</label><textarea id="export-output" rows="8" readonly></textarea></details>
<details><summary>Open the separate answer key</summary><p>Only after you finish. <a id="key-link" href="{{KEY_HREF}}" target="_blank" rel="noopener">Open the answer key</a>. Opening it from here is recorded in your export so your tutor does not count later answers as independent.</p></details>
</section>
</main>
<aside class="outline" aria-label="Question outline">
<p class="label">Questions</p>
<p id="progress-text" aria-live="polite">0 of {{COUNT}} answered</p>
<progress id="progress" max="{{COUNT}}" value="0" aria-label="Answered questions"></progress>
<ol>
{{NAV}}
</ol>
<p class="muted" style="font-size:14px">○ unanswered · ● answered · ⚑ revisit</p>
<a href="#submission">Finish and export ↓</a>
</aside>
</div>
<footer>Original practice made with GPT, I'm Cooked from your supplied course materials. It does not predict your real exam. The answer key is a separate file; keeping it separate supports an honest attempt but does not lock it.</footer>
<script type="application/json" id="artifact-data">{{ARTIFACT_JSON}}</script>
<script>
'use strict';
// Attempt identity, snapshots and exposure follow references/interactive-review.md (schema 1.0).
const artifact=JSON.parse(document.getElementById('artifact-data').textContent);
const sections=[...document.querySelectorAll('.question')];
const total=sections.length;
const sessionId=globalThis.crypto?.randomUUID?.()||('session-'+Date.now()+'-'+Math.random().toString(36).slice(2));
let attemptNumber=1,events=[],snapshots=[],keyOpened=false,dirty=false;
const attemptId=()=>sessionId+':'+attemptNumber;
const now=()=>new Date().toISOString();
function answerOf(s){
  if(s.dataset.kind==='single'||s.dataset.kind==='multi')return [...s.querySelectorAll('fieldset input:checked')].map(x=>x.value);
  return s.querySelector('[name="answer"]').value;
}
function collect(){return sections.map(s=>({item_id:s.id,item_type:s.dataset.kind,topic_id:s.dataset.topic,source_basis:s.dataset.source,
  original_answer:answerOf(s),explanation:s.querySelector('[name="reasoning"]').value,confidence:s.querySelector('[name="confidence"]').value,
  revisit:s.querySelector('[data-flag]').checked,provisional_check:'not graded',
  assistance:{hint_used:false,key_opened_in_page:keyOpened,external_help:'not tracked; tell your tutor'}}));}
function answered(item){return Array.isArray(item.original_answer)?item.original_answer.length>0:item.original_answer.trim().length>0;}
function refresh(){
  const items=collect(),count=items.filter(answered).length;
  document.getElementById('progress-text').textContent=count+' of '+total+' answered';
  document.getElementById('progress').value=count;
  items.forEach(item=>{const span=document.querySelector('[data-nav="'+item.item_id+'"] .status');if(!span)return;
    span.textContent=item.revisit?'⚑':answered(item)?'●':'○';
    span.setAttribute('aria-label',(answered(item)?'Answered':'Unanswered')+(item.revisit?', marked to revisit':''));});
}
function snapshot(reason){snapshots.push({attempt_id:attemptId(),attempt_order:attemptNumber,reason,time:now(),items:collect()});}
const form=document.getElementById('exam');
form.addEventListener('submit',e=>e.preventDefault());
form.addEventListener('input',e=>{const s=e.target.closest&&e.target.closest('.question');
  if(s)events.push({event:'edit',item_id:s.id,attempt_id:attemptId(),attempt_order:attemptNumber,time:now()});dirty=true;refresh();});
function keyAccess(){
  snapshot('before key access');keyOpened=true;dirty=true;  // the exposure itself is unexported evidence
  events.push({event:'key_opened',attempt_id:attemptId(),attempt_order:attemptNumber,time:now()});}
// Click covers mouse and keyboard; auxclick covers middle-click "open in new tab". Opening the key file directly is not detectable.
const keyLink=document.getElementById('key-link');
keyLink.addEventListener('click',keyAccess);
keyLink.addEventListener('auxclick',e=>{if(e.button===1)keyAccess();});
document.getElementById('export').addEventListener('click',()=>{
  snapshot('export');
  const items=collect();
  const data={...artifact,session_id:sessionId,exported_at:now(),attempt_id:attemptId(),attempt_order:attemptNumber,
    items,attempt_history:snapshots,events,persistence:'Exported file only; no automatic tutor or workspace update'};
  const json=JSON.stringify(data,null,2);
  document.getElementById('export-output').value=json;
  document.getElementById('export-panel').open=true;
  try{const url=URL.createObjectURL(new Blob([json],{type:'application/json'}));const a=document.createElement('a');
    a.href=url;a.download=artifact.artifact_id+'-v'+artifact.artifact_version+'-attempt-'+attemptNumber+'.json';document.body.append(a);a.click();a.remove();
    setTimeout(()=>URL.revokeObjectURL(url),10000);}catch(err){/* The copy panel above remains available. */}
  dirty=false;
  document.getElementById('feedback').textContent='Attempt exported: '+items.filter(answered).length+' of '+total+' answered. Attach the JSON file in chat for reviewed feedback.';
});
document.getElementById('retry').addEventListener('click',()=>{
  snapshot('before retry');
  events.push({event:'retry',attempt_id:attemptId(),attempt_order:attemptNumber,time:now()});
  attemptNumber++;form.reset();
  document.getElementById('export-output').value='';document.getElementById('export-panel').open=false;
  refresh();  // dirty is kept: an unexported earlier attempt still lives only in this page
  document.getElementById('feedback').textContent='New attempt started. Earlier answers and any key access stay in the export history.';
});
globalThis.addEventListener?.('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
refresh();
</script>
</body>
</html>
